<script setup>
import { computed, ref } from 'vue';
import { ChevronLeft, ChevronRight, Filter, ImagePlus, MessageCircle, Play, Star, ThumbsDown, ThumbsUp, X } from 'lucide-vue-next';

const props = defineProps({ tripType: { type: String, required: true } });
const activeRating = ref('Semua');
const currentPage = ref(1);
const likedReviews = ref([]);
const isWriteReviewOpen = ref(false);
const uploadInput = ref(null);
const uploadedImages = ref([]);
const selectedMediaIndex = ref(null);
const reviewDraft = ref({ name: '', text: '', rating: 5 });
const reviewsPerPage = 2;
const isPrivateTrip = computed(() => props.tripType === 'private-trip');

const media = computed(() => isPrivateTrip.value ? [
    { src: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=85', alt: 'Pantai Labuan Bajo', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1530053969600-caed2596d242?auto=format&fit=crop&w=900&q=85', alt: 'Aktivitas laut', type: 'video' },
    { src: 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=900&q=85', alt: 'Snorkeling', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=900&q=85', alt: 'Laut Flores', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=900&q=85', alt: 'Pemandangan pulau', type: 'image' },
] : [
    { src: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=85', alt: 'Pulau Pramuka', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=900&q=85', alt: 'Snorkeling wisatawan', type: 'video' },
    { src: 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=900&q=85', alt: 'Pantai pasir putih', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=900&q=85', alt: 'Terumbu karang', type: 'image' },
    { src: 'https://images.unsplash.com/photo-1540202404-a2f29016b523?auto=format&fit=crop&w=900&q=85', alt: 'Senja di pulau', type: 'image' },
]);
const baseReviews = computed(() => isPrivateTrip.value ? [
    { name: 'Nadia Puspita', initials: 'NP', time: '2 minggu lalu', rating: 5, text: 'Rute private trip sangat fleksibel dan kru kapal responsif. Semua kebutuhan rombongan kami dibantu dengan baik.', likes: 46, images: [0, 2] },
    { name: 'Fajar Ramadhan', initials: 'FR', time: '3 minggu lalu', rating: 5, text: 'Labuan Bajo terasa lebih nyaman karena itinerary disusun rapi. Dokumentasinya juga memuaskan.', likes: 38, images: [3] },
    { name: 'Salsa Putri', initials: 'SP', time: '1 bulan lalu', rating: 5, text: 'Pelayanan vendor baik, kapal bersih, dan spot yang dikunjungi sesuai ekspektasi.', likes: 31, images: [] },
    { name: 'Dimas Pratama', initials: 'DP', time: '1 bulan lalu', rating: 4, text: 'Perjalanan nyaman dan pemandu sangat membantu selama aktivitas laut.', likes: 22, images: [1] },
    { name: 'Maya Kirana', initials: 'MK', time: '2 bulan lalu', rating: 5, text: 'Momen sunset di kapal jadi favorit kami. Akan kembali memakai vendor ini.', likes: 18, images: [4] },
] : [
    { name: 'Joko Yusuf Royyan', initials: 'JY', time: '10 bulan lalu', rating: 5, text: 'Secara keseluruhan, pengalaman open trip sangat menyenangkan. Pemandu ramah dan rundown jelas.', likes: 100, images: [0, 1] },
    { name: 'Alya Rahma', initials: 'AR', time: '10 bulan lalu', rating: 5, text: 'Spot snorkelingnya bagus dan aman untuk pemula. Foto dari wisatawan juga sesuai kondisi di lokasi.', likes: 88, images: [2] },
    { name: 'Raka Maulana', initials: 'RM', time: '11 bulan lalu', rating: 5, text: 'Rekomendasi untuk liburan singkat ke Kepulauan Seribu tanpa repot mengurus banyak hal.', likes: 74, images: [3, 4] },
    { name: 'Dinda Aulia', initials: 'DA', time: '11 bulan lalu', rating: 4, text: 'Kapal nyaman, konsumsi cukup, dan guide sangat membantu selama aktivitas laut.', likes: 52, images: [] },
    { name: 'Fikri Ananda', initials: 'FA', time: '1 tahun lalu', rating: 5, text: 'Meeting point mudah ditemukan dan perjalanan berangkat tepat waktu.', likes: 35, images: [0] },
]);
const customReviews = ref([]);
const reviews = computed(() => [...customReviews.value, ...baseReviews.value]);
const displayMedia = computed(() => [...media.value, ...customReviews.value.flatMap((review) => review.uploads || [])]);
const filteredReviews = computed(() => activeRating.value === 'Semua' ? reviews.value : reviews.value.filter((review) => review.rating === Number(activeRating.value)));
const pageCount = computed(() => Math.max(1, Math.ceil(filteredReviews.value.length / reviewsPerPage)));
const visibleReviews = computed(() => filteredReviews.value.slice((currentPage.value - 1) * reviewsPerPage, currentPage.value * reviewsPerPage));
const distribution = [{ label: '5', value: 244, width: '100%' }, { label: '4', value: 0, width: '0%' }, { label: '3', value: 0, width: '0%' }, { label: '2', value: 0, width: '0%' }, { label: '1', value: 0, width: '0%' }];
const selectRating = (rating) => { activeRating.value = rating; currentPage.value = 1; };
const toggleLike = (key) => { likedReviews.value = likedReviews.value.includes(key) ? likedReviews.value.filter((item) => item !== key) : [...likedReviews.value, key]; };
const handleUpload = (event) => { [...event.target.files].slice(0, 4 - uploadedImages.value.length).forEach((file) => uploadedImages.value.push({ src: URL.createObjectURL(file), alt: file.name, type: file.type.startsWith('video') ? 'video' : 'image' })); event.target.value = ''; };
const removeUpload = (index) => uploadedImages.value.splice(index, 1);
const submitReview = () => { if (!reviewDraft.value.name.trim() || !reviewDraft.value.text.trim()) return; customReviews.value.unshift({ name: reviewDraft.value.name, initials: reviewDraft.value.name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(), time: 'Baru saja', rating: reviewDraft.value.rating, text: reviewDraft.value.text, likes: 0, uploads: [...uploadedImages.value], images: [] }); reviewDraft.value = { name: '', text: '', rating: 5 }; uploadedImages.value = []; currentPage.value = 1; activeRating.value = 'Semua'; isWriteReviewOpen.value = false; };
const reviewMedia = (review) => review.uploads || review.images.map((index) => media.value[index]);
</script>

<template>
    <section class="mt-7 overflow-hidden rounded-2xl border border-[#dfeaf5] bg-white shadow-[0_10px_28px_rgba(23,75,120,0.05)]" aria-labelledby="trip-reviews-heading">
        <header class="flex items-center gap-3 border-b border-[#e8f0f7] px-5 py-5 sm:px-7"><span class="grid size-10 place-items-center rounded-xl bg-[#e8f4ff] text-[#1688e8]"><Star class="size-5 fill-current" /></span><div><p class="text-[10px] font-bold uppercase tracking-[0.16em] text-[#1688e8]">Cerita dari wisatawan</p><h2 id="trip-reviews-heading" class="mt-0.5 text-xl font-extrabold tracking-tight text-[#173b70]">Rating & ulasan perjalanan</h2></div></header>
        <div class="border-b border-[#e8f0f7] bg-[#fbfdff] px-5 py-6 sm:px-7"><div class="flex items-end justify-between gap-4"><div><h3 class="text-base font-extrabold text-[#173b70]">Foto & video wisatawan</h3><p class="mt-1 text-xs text-[#7186a2]">Pengalaman asli peserta di sepanjang perjalanan.</p></div><button type="button" class="group inline-flex shrink-0 items-center gap-1 text-xs font-bold text-[#1688e8]" @click="selectedMediaIndex = 0">Lihat galeri <ChevronRight class="size-4 transition-transform group-hover:translate-x-0.5" /></button></div><div class="mt-4 flex gap-3 overflow-x-auto pb-2 [scrollbar-width:thin]"><button v-for="(item, index) in media" :key="item.src" type="button" class="group relative h-32 w-48 shrink-0 overflow-hidden rounded-xl bg-slate-100 text-left ring-offset-2 transition hover:-translate-y-0.5 hover:shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1688e8]" :class="index === 0 ? 'w-80 sm:w-96' : ''" @click="selectedMediaIndex = index"><img :src="item.src" :alt="item.alt" class="size-full object-cover transition duration-500 group-hover:scale-110" /><span class="absolute inset-0 bg-gradient-to-t from-[#071a32]/45 via-transparent to-transparent"></span><span v-if="index === 0" class="absolute bottom-3 left-3 text-xs font-extrabold text-white">Momen dari trip ini</span><span v-if="item.type === 'video'" class="absolute inset-0 grid place-items-center"><span class="grid size-10 place-items-center rounded-full bg-white/95 text-[#1688e8] shadow-lg"><Play class="ml-0.5 size-4 fill-current" /></span></span><span v-if="index === media.length - 1" class="absolute inset-0 grid place-items-center bg-[#071a32]/65 text-xl font-extrabold text-white">+79</span></button></div></div>
        <div class="grid lg:grid-cols-[300px_minmax(0,1fr)]"><aside class="border-b border-[#e8f0f7] bg-[#f3f8fe] p-5 sm:p-6 lg:border-b-0 lg:border-r"><p class="text-[10px] font-bold uppercase tracking-[0.14em] text-[#1688e8]">Penilaian peserta</p><div class="mt-3 flex items-center gap-4"><div class="rounded-xl bg-white px-3 py-3 text-center shadow-[0_5px_14px_rgba(31,87,143,0.08)]"><p class="text-3xl font-extrabold tracking-tight text-[#173b70]">5.0</p><div class="mt-1 flex justify-center gap-0.5 text-[#f5a000]"><Star v-for="index in 5" :key="index" class="size-3.5 fill-current" /></div><p class="mt-1.5 text-[10px] font-semibold text-[#7186a2]">244 ulasan</p></div><div class="min-w-0 flex-1 space-y-1.5"><div v-for="item in distribution" :key="item.label" class="grid grid-cols-[12px_minmax(0,1fr)_20px] items-center gap-2 text-[10px]"><span class="font-bold text-[#60789c]">{{ item.label }}</span><span class="h-1.5 overflow-hidden rounded-full bg-white"><span class="block h-full rounded-full bg-[#f5a000]" :style="{ width: item.width }"></span></span><span class="text-right font-bold text-[#60789c]">{{ item.value }}</span></div></div></div><div class="mt-6 border-t border-[#d9e8f5] pt-5"><div class="flex items-center gap-2 text-xs font-extrabold text-[#173b70]"><Filter class="size-3.5 text-[#1688e8]" />Pilih rating ulasan</div><div class="mt-3 flex flex-wrap gap-2"><button v-for="option in ['Semua', '5', '4', '3', '2', '1']" :key="option" type="button" class="rounded-lg border px-3 py-1.5 text-[11px] font-bold transition" :class="activeRating === option ? 'border-[#1688e8] bg-[#1688e8] text-white shadow-sm' : 'border-white bg-white text-[#55739b] hover:border-[#1688e8] hover:text-[#1688e8]'" @click="selectRating(option)">{{ option === 'Semua' ? 'Semua' : `${option} ★` }}</button></div></div></aside>
            <div class="min-w-0 bg-white p-5 sm:p-6"><div class="mb-4 flex items-center justify-between"><p class="text-xs font-extrabold text-[#173b70]">Ulasan peserta</p><span class="rounded-full bg-[#edf7ff] px-2.5 py-1 text-[10px] font-bold text-[#1688e8]">{{ filteredReviews.length }} ulasan</span></div><div class="grid gap-4 md:grid-cols-2"><article v-for="(review, index) in visibleReviews" :key="`${review.name}-${review.time}-${index}`" class="flex min-w-0 flex-col rounded-xl border border-[#e1ebf6] border-t-2 border-t-[#d9edff] bg-white p-4"><div class="flex items-start gap-3"><span class="grid size-9 shrink-0 place-items-center rounded-xl bg-[#e8f4ff] text-[10px] font-extrabold text-[#1688e8]">{{ review.initials }}</span><div class="min-w-0"><h3 class="truncate text-xs font-extrabold text-[#31577f]">{{ review.name }}</h3><p class="mt-1 text-[10px] text-[#9aacc0]">{{ review.time }}</p></div></div><div class="mt-3 flex gap-0.5 text-[#f5a000]"><Star v-for="star in review.rating" :key="star" class="size-3.5 fill-current" /></div><p class="mt-3 text-[11px] leading-5 text-[#60789c]">{{ review.text }}</p><div v-if="reviewMedia(review).length" class="mt-3 flex gap-2"><button v-for="item in reviewMedia(review).slice(0, 3)" :key="item.src" type="button" class="relative size-14 overflow-hidden rounded-lg ring-1 ring-[#e1ebf6]" @click="selectedMediaIndex = displayMedia.findIndex((mediaItem) => mediaItem.src === item.src)"><img :src="item.src" :alt="item.alt" class="size-full object-cover" /><span v-if="item.type === 'video'" class="absolute inset-0 grid place-items-center bg-[#071a32]/30 text-white"><Play class="size-4 fill-current" /></span></button></div><div class="mt-auto flex items-center gap-3 border-t border-[#edf3f8] pt-3" :class="reviewMedia(review).length ? 'mt-3' : 'mt-3'"><button type="button" class="inline-flex items-center gap-1 text-[10px] font-semibold" :class="likedReviews.includes(`${currentPage}-${index}`) ? 'text-[#1688e8]' : 'text-[#9aacc0]'" @click