    </section>
    <Teleport to="body"><div v-if="selectedMediaIndex !== null" class="fixed inset-0 z-[110] flex items-center justify-center bg-[#071a32]/90 p-4 sm:p-8" role="dialog" aria-modal="true" aria-label="Preview foto wisatawan" @click.self="selectedMediaIndex = null"><div class="flex h-full w-full max-w-6xl flex-col"><header class="flex items-center justify-between pb-4 text-white"><div><p class="text-sm font-bold">Foto & video wisatawan</p><p class="mt-0.5 text-xs text-white/65">{{ selectedMediaIndex + 1 }} dari {{ displayMedia.length }} media</p></div><button type="button" class="grid size-10 place-items-center rounded-full bg-white/12 transition hover:bg-white/20" aria-label="Tutup preview" @click="selectedMediaIndex = null"><X class="size-5" /></button></header><div class="relative min-h-0 flex-1 overflow-hidden rounded-2xl bg-black"><img :src="displayMedia[selectedMediaIndex].src" :alt="displayMedia[selectedMediaIndex].alt" class="size-full object-contain" /><span v-if="displayMedia[selectedMediaIndex].type === 'video'" class="absolute inset-0 grid place-items-center"><span class="grid size-16 place-items-center rounded-full bg-white/90 text-[#1688e8]"><Play class="ml-1 size-7 fill-current" /></span></span><button type="button" class="absolute left-4 top-1/2 grid size-10 -translate-y-1/2 place-items-center rounded-full bg-white/90 text-[#1688e8]" @click="selectedMediaIndex = (selectedMediaIndex - 1 + displayMedia.length) % displayMedia.length"><ChevronLeft class="size-5" /></button><button type="button" class="absolute right-4 top-1/2 grid size-10 -translate-y-1/2 place-items-center rounded-full bg-white/90 text-[#1688e8]" @click="selectedMediaIndex = (selectedMediaIndex + 1) % displayMedia.length"><ChevronRight class="size-5" /></button></div><div class="mt-3 flex gap-2 overflow-x-auto pb-1"><button v-for="(item, index) in displayMedia" :key="item.src" type="button" class="size-16 shrink-0 overflow-hidden rounded-lg border-2" :class="index === selectedMediaIndex ? 'border-[#52a6ff]' : 'border-transparent opacity-60'" @click="selectedMediaIndex = index"><img :src="item.src" :alt="item.alt" class="size-full object-cover" /></button></div></div></div></Teleport>
    <Teleport to="body"><div v-if="isWriteReviewOpen" class="fixed inset-0 z-[110] flex items-center justify-center bg-[#071a32]/60 p-4" role="dialog" aria-modal="true" aria-label="Tulis ulasan" @click.self="isWriteReviewOpen = false"><form class="w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl" @submit.prevent="submitReview"><header class="flex items-center justify-between border-b border-[#e8f0f7] px-5 py-4"><div><h2 class="text-base font-extrabold text-[#173b70]">Bagikan pengalamanmu</h2><p class="mt-0.5 text-[11px] text-[#7186a2]">Tambahkan foto agar wisatawan lain mendapat gambaran trip.</p></div><button type="button" class="rounded-full p-2 text-[#60789c] hover:bg-[#f1f6fb]" aria-label="Tutup" @click="isWriteReviewOpen = false"><X class="size-5" /></button></header><div class="space-y-4 p-5"><label class="block text-xs font-bold text-[#31577f]">Nama<input v-model="reviewDraft.name" required type="text" placeholder="Nama kamu" class="mt-2 w-full rounded-lg border border-[#dce8f3] px-3 py-2.5 text-sm outline-none transition placeholder:text-[#a8b7c8] focus:border-[#1688e8] focus:ring-2 focus:ring-[#1688e8]/15" /></label><div><p class="text-xs font-bold text-[#31577f]">Rating</p><div class="mt-2 flex gap-1"><button v-for="star in 5" :key="star" type="button" class="p-0.5" :aria-label="`Beri ${star} bintang`" @click="reviewDraft.rating = star"><Star class="size-6" :class="star <= reviewDraft.rating ? 'fill-[#f5a000] text-[#f5a000]' : 'text-[#dbe6f0]'" /></button></div></div><label class="block text-xs font-bold text-[#31577f]">Ulasan<textarea v-model="reviewDraft.text" required rows="4" placeholder="Ceritakan pengalaman trip kamu" class="mt-2 w-full resize-none rounded-lg border border-[#dce8f3] px-3 py-2.5 text-sm outline-none transition placeholder:text-[#a8b7c8] focus:border-[#1688e8] focus:ring-2 focus:ring-[#1688e8]/15"></textarea></label><div><div class="flex items-center justify-between"><p class="text-xs font-bold text-[#31577f]">Foto atau video</p><span class="text-[10px] text-[#7186a2]">Maks. 4 file</span></div><input ref="uploadInput" type="file" accept="image/*,video/*" multiple class="hidden" @change="handleUpload" /><div class="mt-2 flex flex-wrap gap-2"><button v-for="(item, index) in uploadedImages" :key="item.src" type="button" class="group relative size-16 overflow-hidden rounded-lg"><img :src="item.src" :alt="item.alt" class="size-full object-cover" /><span class="absolute right-1 top-1 grid size-5 place-items-center rounded-full bg-white text-[#173b70] shadow" @click.stop="removeUpload(index)"><X class="size-3" /></span></button><button v-if="uploadedImages.length < 4" type="button" class="grid size-16 place-items-center rounded-lg border border-dashed border-[#a8cfee] bg-[#f7fbff] text-[#1688e8] transition hover:border-[#1688e8] hover:bg-[#edf7ff]" aria-label="Unggah foto atau video" @click="uploadInput?.click()"><ImagePlus class="size-5" /></button></div></div></div><footer class="flex justify-end gap-3 border-t border-[#e8f0f7] px-5 py-4"><button type="button" class="px-3 py-2 text-xs font-bold text-[#60789c] hover:text-[#173b70]" @click="isWriteReviewOpen = false">Batal</button><button type="submit" class="rounded-lg bg-[#1688e8] px-4 py-2 text-xs font-bold text-white shadow-sm transition hover:bg-[#0876d2]">Kirim ulasan</button></footer></form></div></Teleport>
</template>
